{ let mut variants = BTreeSet :: new () ; let mut declarations = String :: new () ; let mut arms = String :: new () ; for row in & dataset . rows { let id = row . get ("id") . and_then (serde_json :: Value :: as_str) . ok_or ("number: absent id") ? ; let variant : String = id . strip_prefix ("num:") . unwrap_or (id) . split ([':' , '-']) . map (| word | { let mut letters = word . chars () ; letters . next () . map_or_else (String :: new , | first | first . to_ascii_uppercase () . to_string () + letters . as_str ()) }) . collect () ; if ! variants . insert (variant . clone ()) { return Err (format ! ("number: ambiguous Rust id {id}") . into ()) ; } let declaration = format ! ("id = "{id}"") ; let start = input . find (& declaration) . ok_or ("number: typed ids require canonical input fields") ? ; let rest = & input [start + declaration . len () ..] ; let prefix = "value = "" ; let offset = rest . find (prefix) . ok_or ("number: absent canonical value field") ? ; let begin = start + declaration . len () + offset + prefix . len () ; let value = row . get ("value") . and_then (serde_json :: Value :: as_str) . ok_or ("number: absent value") ? ; let end = begin + value . len () ; if input . get (begin .. end) != Some (value) || ! input [end ..] . starts_with ('"') { return Err (format ! ("number: noncanonical value field for {id}") . into ()) ; } writeln ! (declarations , "    /// Registry id: {id}.
    {variant},") ? ; writeln ! (arms , "    ({}, {})," , rust_integer_literal (begin) , rust_integer_literal (end)) ? ; } let count = dataset . rows . len () ; let generated = format ! ("// Generated by the documents input projection. Values remain in their committed carriers.

/// A declared numeric pin; removing an id removes its variant.
#[derive(Clone, Copy, Debug)]
pub enum NumberId {{
{declarations}}}

const OFFSETS: [(usize, usize); {count}] = [
{arms}];

impl NumberId {{
    /// Read the full-precision value from the committed registry.
    ///
    /// # Panics
    /// Panics only if generated offsets differ from the registry, which the fixed-point gate refuses.
    #[must_use]
    pub fn value(self) -> &'static str {{
        let (start, end) = OFFSETS[self as usize];
        include_str!("{carrier_name}")
            .get(start..end)
            .expect("registry offsets must be regenerated")
    }}

    /// Read an unsigned integer pin without a second literal.
    ///
    /// # Panics
    /// Panics only if the selected pin is not an unsigned machine integer, which a correctly typed consumer selection cannot arrange.
    #[must_use]
    pub fn integer(self) -> u64 {{
        self.value().parse().expect("registry pin must be an unsigned integer")
    }}
}}
") ; Ok (generated) }
